pub fn spiral(m: List[List[Int]]) -> List[Int] {
  let empty: List[Int] = []
  var out: List[Int] = []
  var top = 0
  var bottom = m.len() - 1
  var left = 0
  var right = m.get_or(0, empty).len() - 1
  while top <= bottom and left <= right {
    for c in range(left, right + 1) {
      out = out.push(m.get_or(top, empty).get_or(c, 0))
    }
    top = top + 1
    for r in range(top, bottom + 1) {
      out = out.push(m.get_or(r, empty).get_or(right, 0))
    }
    right = right - 1
    if top <= bottom {
      for k in range(0, right - left + 1) {
        out = out.push(m.get_or(bottom, empty).get_or(right - k, 0))
      }
      bottom = bottom - 1
    }
    if left <= right and top <= bottom {
      for k in range(0, bottom - top + 1) {
        out = out.push(m.get_or(bottom - k, empty).get_or(left, 0))
      }
      left = left + 1
    }
  }
  return out
}
